/*
 * <runner-avatar> — Runner #10592, front view with idle breathing and a tap-to-jump cheer.
 *
 * Usage (load runner-avatar.js with a script tag, then):
 *   <runner-avatar style="width:260px;height:360px"></runner-avatar>
 * Attributes:
 *   no-tap      tapping does not trigger the jump (use el.cheer() from code instead)
 *   no-idle     turn off the idle breathing motion
 *   shadow      "off" hides the floor shadow
 * JS API: el.cheer()  — play the jump once (e.g. after a run is saved)
 * Events: "cheer" fired when a jump starts
 * Note: <runner-spin> is registered as an alias so existing markup keeps working.
 */
(function () {
  const SRC = "data:image/webp;base64,";
  const JUMP_S = 0.8;

  const tpl = document.createElement("template");
  tpl.innerHTML = `
  <style>
    :host{display:inline-block;position:relative;width:260px;height:360px;user-select:none;-webkit-user-select:none;
          cursor:pointer;outline:none;-webkit-tap-highlight-color:transparent}
    :host([no-tap]){cursor:default}
    .body{position:absolute;inset:0;transform-origin:50% 100%;will-change:transform}
    img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;object-position:50% 100%;
        pointer-events:none;-webkit-user-drag:none}
    .shadow{position:absolute;left:50%;bottom:1.2%;width:44%;height:5%;transform:translateX(-50%);
        border-radius:50%;background:radial-gradient(closest-side,rgba(40,30,20,.3),rgba(40,30,20,0));pointer-events:none}
  </style>
  <div class="shadow"></div><div class="body"><img alt="Runner #10592"></div>`;

  class RunnerAvatar extends HTMLElement {
    static get observedAttributes() { return ["shadow"]; }
    constructor() {
      super();
      const root = this.attachShadow({ mode: "open" });
      root.appendChild(tpl.content.cloneNode(true));
      root.querySelector("img").src = SRC;
      this._body = root.querySelector(".body");
      this._shadow = root.querySelector(".shadow");
      this._jumpT = -1;
      this._tick = this._tick.bind(this);
      this._onTap = () => { if (!this.hasAttribute("no-tap")) this.cheer(); };
      this._onKey = (e) => { if (e.key === " " || e.key === "Enter") { e.preventDefault(); this._onTap(); } };
    }
    connectedCallback() {
      if (!this.hasAttribute("tabindex")) this.tabIndex = 0;
      this.setAttribute("role", "button");
      if (!this.hasAttribute("aria-label")) this.setAttribute("aria-label", "Runner #10592，點一下會跳起來");
      this.addEventListener("click", this._onTap);
      this.addEventListener("keydown", this._onKey);
      this._raf = requestAnimationFrame(this._tick);
    }
    disconnectedCallback() {
      cancelAnimationFrame(this._raf);
      this.removeEventListener("click", this._onTap);
      this.removeEventListener("keydown", this._onKey);
    }
    attributeChangedCallback() {
      this._shadow.style.display = this.getAttribute("shadow") === "off" ? "none" : "";
    }
    cheer() {
      if (this._jumpT >= 0 && this._jumpT < JUMP_S * 0.7) return;   // ignore taps mid-jump
      this._jumpT = 0;
      this.dispatchEvent(new CustomEvent("cheer"));
    }
    _tick(now) {
      const dt = Math.min(0.05, (now - (this._last || now)) / 1000); this._last = now;
      const s = now / 1000;
      const idle = !this.hasAttribute("no-idle");
      let y = 0, sx = 1, sy = 1;
      if (idle) { sy += Math.sin(s * 2.2) * 0.008; sx -= Math.sin(s * 2.2) * 0.004; }
      if (this._jumpT >= 0) {
        this._jumpT += dt;
        const c = this._jumpT / JUMP_S;
        if (c < 0.16) {                                   // anticipation: crouch
          const k = Math.sin((c / 0.16) * Math.PI / 2);
          sy *= 1 - 0.08 * k; sx *= 1 + 0.05 * k;
        } else if (c < 0.82) {                            // airborne: up and down, stretched
          const k = (c - 0.16) / 0.66;
          y = -Math.sin(k * Math.PI) * 14;
          const st = Math.sin(k * Math.PI);
          sy *= 1 + 0.05 * (1 - st) * (k < 0.5 ? 1 : 0.4); sx *= 1 - 0.03 * (1 - st);
        } else if (c < 1) {                               // landing squash and settle
          const k = (c - 0.82) / 0.18;
          const q = Math.sin(k * Math.PI) * (1 - k * 0.3);
          sy *= 1 - 0.07 * q; sx *= 1 + 0.045 * q;
        } else this._jumpT = -1;
      }
      this._body.style.transform = `translateY(${y.toFixed(2)}%) scale(${sx.toFixed(4)}, ${sy.toFixed(4)})`;
      const sh = Math.max(0.5, 1 + y / 24);
      this._shadow.style.transform = `translateX(-50%) scale(${sh.toFixed(3)})`;
      this._shadow.style.opacity = sh.toFixed(3);
      this._raf = requestAnimationFrame(this._tick);
    }
  }
  if (!customElements.get("runner-avatar")) customElements.define("runner-avatar", RunnerAvatar);
  if (!customElements.get("runner-spin")) customElements.define("runner-spin", class extends RunnerAvatar {});
})();
